import { installationChannel } from '../install/installationChannel';

const DEFAULT_PORTS = {
  production: 16060,
  local: 16061,
} as const;
const MAX_PORT = 65535;
const PORT_PATTERN = /^(0|[1-9]\d*)$/;

export const hubPort = (env: NodeJS.ProcessEnv = process.env): number => {
  const configured = env.RIVET_LIBRARY_PORT;
  if (configured === undefined) return DEFAULT_PORTS[installationChannel(env)];
  if (!PORT_PATTERN.test(configured))
    throw new Error(`Invalid RIVET_LIBRARY_PORT: ${configured}`);
  const port = Number(configured);
  if (!Number.isInteger(port) || port > MAX_PORT)
    throw new Error(`Invalid RIVET_LIBRARY_PORT: ${configured}`);
  return port;
};
